.crate-hero{background:#e59000;color:#111;padding:0 7%;overflow:hidden}.hero-inner{max-width:1440px;margin:auto}.hero-nav{display:flex;align-items:center;justify-content:space-between;gap:32px;padding:25px 0}.hero-brand{color:#111;text-decoration:none;font:800 24px/1 var(--heading);letter-spacing:-.05em}.hero-brand sup{font-size:11px;vertical-align:super;margin-left:2px}.hero-links{display:flex;align-items:center;gap:clamp(24px,6vw,95px)}.hero-links a{font:600 12px/1.4 var(--heading);color:#111;text-decoration:none;transition:opacity .2s}.hero-links a:hover{opacity:.55}.hero-composition{position:relative;margin-top:80px;padding-bottom:105px}.hero-title{margin:0;color:#111;font-family:var(--heading);font-weight:900;font-size:clamp(72px,12vw,190px);line-height:.9;letter-spacing:-.05em}.hero-line{display:block;width:max-content;max-width:100%;animation:hero-enter .65s cubic-bezier(.2,.65,.3,1) both}.hero-line-two{margin-top:24px;margin-left:40%;animation-delay:.1s}.hero-copy{position:absolute;left:0;top:calc(clamp(72px,12vw,190px) * .9 + 35px);max-width:37%;font:400 clamp(10px,.85vw,13px)/1.55 var(--sans)}.hero-copy p{margin:0 0 19px}.hero-cta{display:inline-block;position:relative;padding-bottom:9px;color:#111;text-decoration:none;font:600 12px/1.3 var(--heading)}.hero-cta:after{content:'';position:absolute;bottom:0;left:0;width:100%;height:1px;background:#111;transform-origin:left;transition:transform .25s}.hero-cta:hover:after{transform:scaleX(.6)}#catalog-app{scroll-margin-top:25px}#o-danych,#kontakt{scroll-margin-top:25px}.contact-heading{font:700 20px/1.3 var(--heading);color:#e28d00}
